const ts = require('typescript');
const path = require('path');
const configPath = path.resolve('tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, path.dirname(configPath), { module: ts.ModuleKind.ESNext });
const files = [
  'src/screens/appointments-screen/appointments-screen.tsx',
  'src/screens/home/home-screen/home-screen.tsx',
  'src/screens/home/home-screen/home-screen.utils.ts',
  'src/store/AppContext.tsx',
  'src/store/refresh-cold-start-geolocation.ts',
  '__tests__/appointments-screen.test.tsx',
  '__tests__/fake-geolocation.test.ts',
  '__tests__/refresh-cold-start-geolocation.test.ts',
].map((f) => path.resolve(f));
const rootNames = Array.from(new Set([...parsed.fileNames, ...files]));
const program = ts.createProgram({ rootNames, options: parsed.options });
const diags = [];
for (const file of files) {
  const sf = program.getSourceFile(file);
  if (!sf) {
    console.log('MISSING', file);
    continue;
  }
  const suggestions = program.getSuggestionDiagnostics(sf);
  for (const d of suggestions) {
    const { line } = sf.getLineAndCharacterOfPosition(d.start ?? 0);
    diags.push(`${path.relative(process.cwd(), file)}:${line + 1} ${ts.flattenDiagnosticMessageText(d.messageText, ' ')} [${d.code}]`);
  }
}
console.log(diags.length ? diags.join('\n') : 'NO_SUGGESTION_DIAGNOSTICS');
EOF

