import React from 'react';
import TestRenderer, {act} from 'react-test-renderer';

import routeNames from '../src/navigation/route-names';

interface RecordedScreen {
  componentName?: string;
  name: string;
}

const recordedScreens: RecordedScreen[] = [];
let recordedInitialRouteName: string | undefined;

jest.mock('react-native-extended-stylesheet', () => ({
  __esModule: true,
  default: {
    create: <T,>(styleSheet: T): T => styleSheet,
  },
}));

jest.mock('react-native-config', () => ({
  __esModule: true,
  default: {},
}));

jest.mock('react-native-biometrics', () =>
  jest.fn().mockImplementation(() => ({
    simplePrompt: jest.fn(),
  })),
);

jest.mock('react-native-reanimated', () => ({
  __esModule: true,
  default: {
    View: 'MockAnimatedView',
  },
  FadeInRight: {duration: (): object => ({})},
  FadeInUp: {springify: (): object => ({})},
  FadeOutDown: {springify: (): object => ({})},
}));

jest.mock('react-native-modal', () => 'MockModal');

jest.mock('@react-navigation/bottom-tabs', () => {
  const ReactModule = require('react');

  return {
    createBottomTabNavigator: (): {
      Navigator: React.FC<{
        children?: React.ReactNode;
        initialRouteName?: string;
      }>;
      Screen: React.FC<{
        component?: {displayName?: string; name?: string};
        name: string;
      }>;
    } => ({
      Navigator: ({children, initialRouteName}): React.ReactElement => {
        recordedInitialRouteName = initialRouteName;
        return ReactModule.createElement(ReactModule.Fragment, null, children);
      },
      Screen: ({component, name}): null => {
        recordedScreens.push({
          componentName: component?.displayName ?? component?.name,
          name,
        });
        return null;
      },
    }),
  };
});

jest.mock('@store/AppContext.tsx', () => ({
  useAppState: (): {user: {contacts: Array<{value: string}>}} => ({
    user: {contacts: [{value: ''}]},
  }),
}));

const mockScreen = (displayName: string) => {
  const Screen = (): null => null;
  Screen.displayName = displayName;
  return Screen;
};

jest.mock('@screens/appointments-screen/appointments-screen', () => ({
  __esModule: true,
  default: mockScreen('AppointmentsScreen'),
}));
jest.mock('@screens/home/home-screen/home-screen', () => ({
  __esModule: true,
  default: mockScreen('HomeScreen'),
}));
jest.mock('@screens/consult-screen/consult-screen', () => ({
  __esModule: true,
  default: mockScreen('ConsultScreen'),
}));
jest.mock('@screens/concierge-screen/concierge-screen', () => ({
  __esModule: true,
  default: mockScreen('ConciergeScreen'),
}));
jest.mock('@screens/profile/profile-screen/profile-screen', () => ({
  __esModule: true,
  default: mockScreen('ProfileScreen'),
}));

import MainTabNavigator from '../src/navigation/main-tab/main-tab-navigator';

const globalWithTabDependencies = global as typeof globalThis & {
  $i18n: {t: (key: string) => string};
  $routeNames: typeof routeNames;
};

globalWithTabDependencies.$i18n = {
  t: (key: string): string => key,
};
globalWithTabDependencies.$routeNames = routeNames;

describe('MainTabNavigator appointments tab', () => {
  beforeEach(() => {
    recordedScreens.length = 0;
    recordedInitialRouteName = undefined;
  });

  test('registers the appointments screen without opening it first', () => {
    act(() => {
      TestRenderer.create(<MainTabNavigator />);
    });

    expect(recordedInitialRouteName).toBe(routeNames.home);
    expect(recordedScreens.map((screen) => screen.name)).toEqual([
      routeNames.home,
      routeNames.consult,
      routeNames.appointments,
      routeNames.profile,
    ]);
    expect(
      recordedScreens.find((screen) => screen.name === routeNames.appointments)
        ?.componentName,
    ).toBe('AppointmentsScreen');
  });
});

