const ts = require('typescript');
const configPath = ts.findConfigFile('./', ts.sys.fileExists, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, './');
const files = [
  'src/screens/appointments-screen/appointments-screen.tsx',
  'src/screens/appointments-screen/appointments-screen.styles.ts',
  'src/screens/consult-screen/consult-screen.tsx',
  'src/screens/consult-screen/consult-screen.styles.ts',
  'src/screens/consult-screen/consult-doctor-list.tsx',
  'src/screens/consult-screen/consult-doctor-list-reset.ts',
];
const program = ts.createProgram({ rootNames: parsed.fileNames, options: parsed.options });
const all = ts.getPreEmitDiagnostics(program);
const suggestions = [];
for (const sf of program.getSourceFiles()) {
  if (files.some((f) => sf.fileName.endsWith(f))) {
    suggestions.push(...program.getSuggestionDiagnostics(sf));
  }
}
const relevant = [...all, ...suggestions].filter((d) =>
  files.some((f) => (d.file?.fileName ?? '').endsWith(f))
);
console.log('program files', parsed.fileNames.length, 'relevant diags', relevant.length);
for (const d of relevant) {
  const pos = d.file && d.start != null ? d.file.getLineAndCharacterOfPosition(d.start) : null;
  console.log(
    `${d.file?.fileName}:${pos ? pos.line + 1 : '?'}:${pos ? pos.character + 1 : '?'} TS${d.code} ${ts.flattenDiagnosticMessageText(d.messageText, ' ')}`
  );
}
EOF

