import React from 'react';
import TestRenderer, {act} from 'react-test-renderer';

interface RegisteredTabScreen {
  component: React.ComponentType;
  name: string;
}

const registeredScreens: RegisteredTabScreen[] = [];
let capturedInitialRouteName: string | undefined;

jest.mock('react-native-extended-stylesheet', () => ({
  __esModule: true,
  default: {
    create: <T,>(styles: T): T => styles,
  },
}));

jest.mock('react-native-config', () => ({
  __esModule: true,
  default: {},
}));

jest.mock('@react-navigation/bottom-tabs', () => {
  const ReactModule = require('react');

  return {
    createBottomTabNavigator: () => ({
      Navigator: ({
        children,
        initialRouteName,
      }: {
        children: React.ReactNode;
        initialRouteName?: string;
      }): React.ReactElement => {
        capturedInitialRouteName = initialRouteName;
        return ReactModule.createElement(ReactModule.Fragment, null, children);
      },
      Screen: ({
        component,
        name,
      }: RegisteredTabScreen): null => {
        registeredScreens.push({component, name});
        return null;
      },
    }),
  };
});

jest.mock('@screens/home/home-screen/home-screen', () => 'HomeScreen');
jest.mock(
  '@screens/consult-screen/consult-screen',
  () => 'ConsultScreen',
);
jest.mock(
  '@screens/appointments-screen/appointments-screen',
  () => 'AppointmentsScreen',
);
jest.mock(
  '@screens/concierge-screen/concierge-screen',
  () => 'ConciergeScreen',
);
jest.mock(
  '@screens/profile/profile-screen/profile-screen',
  () => 'ProfileScreen',
);

jest.mock('@store/AppContext.tsx', () => ({
  useAppState: (): {user: null} => ({user: null}),
}));

jest.mock('react-native-biometrics', () =>
  jest.fn().mockImplementation(() => ({
    simplePrompt: jest.fn(),
  })),
);

jest.mock('react-native-modal', () => 'Modal');

import MainTabNavigator from '../src/navigation/main-tab/main-tab-navigator';

describe('MainTabNavigator appointments tab', () => {
  beforeEach(() => {
    registeredScreens.length = 0;
    capturedInitialRouteName = undefined;
  });

  test('shows the appointments screen from the tab bar and still opens on home', () => {
    act(() => {
      TestRenderer.create(<MainTabNavigator />);
    });

    const appointmentsScreen = registeredScreens.find(
      (screen: RegisteredTabScreen): boolean =>
        screen.name === 'AppointmentsScreen',
    );

    expect(appointmentsScreen?.component).toBe('AppointmentsScreen');
    expect(capturedInitialRouteName).toBe('HomeScreen');
  });
});

