  '__tests__/consult-screen.test.tsx',
  '__tests__/consult-schedule-days.test.ts',
];
const rootNames = Array.from(new Set([...parsed.fileNames, ...extra.map((file) => path.resolve(file))]));
const program = ts.createProgram({ rootNames, options: parsed.options });
const changed = new Set([
  'src/api/api.ts',
  'src/i18n/locale/Indonesia.ts',
  'src/i18n/locale/Melayu.ts',
  'src/i18n/locale/en.ts',
  'src/i18n/locale/ph.ts',
  'src/i18n/locale/th.ts',
  'src/i18n/locale/vn.ts',
  'src/i18n/locale/zh.ts',
  'src/i18n/locale/zh_tw.ts',
  'src/screens/consult-screen/consult-doctor-list.tsx',
  'src/screens/consult-screen/consult-screen.styles.ts',
  'src/screens/consult-screen/consult-screen.tsx',
  'src/screens/consult-screen/consult-schedule-days.ts',
  'src/screens/consult-screen/consult-schedule-strip.tsx',
  ...extra,
].map((file) => path.resolve(file)));
const interesting = new Set([
  ts.DiagnosticCategory.Error,
  ts.DiagnosticCategory.Warning,
  ts.DiagnosticCategory.Suggestion,
  ts.DiagnosticCategory.Message,
]);
let count = 0;
for (const sourceFile of program.getSourceFiles()) {
  if (!changed.has(sourceFile.fileName)) continue;
  const diagnostics = [
    ...program.getSemanticDiagnostics(sourceFile),
    ...program.getSyntacticDiagnostics(sourceFile),
    ...program.getSuggestionDiagnostics(sourceFile),
  ];
  for (const diagnostic of diagnostics) {
    if (!interesting.has(diagnostic.category) && diagnostic.category !== ts.DiagnosticCategory.Error) continue;
    const message = ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n');
    const pos = diagnostic.start != null ? sourceFile.getLineAndCharacterOfPosition(diagnostic.start) : null;
    const line = pos ? pos.line + 1 : 0;
    const rel = path.relative(process.cwd(), sourceFile.fileName);
    console.log(`${rel}:${line} TS${diagnostic.code} [${ts.DiagnosticCategory[diagnostic.category]}] ${message}`);
    count += 1;
  }
}
console.log(`TOTAL ${count}`);
