const isGeneralPracticeDoctor = (item: QueueItem): boolean => {
  const doctor = item.doctor;

  if (!doctor) {
    return false;
  }

  const specialties = Array.isArray(doctor.specialties)
    ? doctor.specialties
    : [];
  const labels = [doctor.type, ...specialties].filter(
    (label: unknown): label is string =>
      typeof label === 'string' && label.trim().length > 0,
  );

  return labels.some((label: string): boolean => {
    if (isGeneralPracticeCoverageLabel(label)) {
      return true;
    }

    const translated = translateLabel(label);

    return (
      translated !== label && isGeneralPracticeCoverageLabel(translated)
    );
  });
};

