import {
  createEmbeddedWebViewSafeAreaScript,
  embeddedWebViewSafeAreaScript,
} from '../src/components/webView-comp/embedded-web-view-safe-area';

interface FakeNode {
  id: string;
  textContent: string;
  innerHTML: string;
  style: Record<string, string>;
  children: FakeNode[];
  setAttribute: (name: string, value: string) => void;
  appendChild: (child: FakeNode) => FakeNode;
  querySelector: (selector: string) => FakeNode | null;
}

const createNode = (): FakeNode => {
  const node: FakeNode = {
    id: '',
    textContent: '',
    innerHTML: '',
    style: {},
    children: [],
    setAttribute: (): void => undefined,
    appendChild: (child: FakeNode): FakeNode => {
      node.children.push(child);

      return child;
    },
    querySelector: (): FakeNode | null => null,
  };

  return node;
};

const findById = (node: FakeNode, id: string): FakeNode | null =>
  node.id === id
    ? node
    : node.children.reduce<FakeNode | null>(
        (found: FakeNode | null, child: FakeNode): FakeNode | null =>
          found ?? findById(child, id),
        null,
      );

const runScriptOnGPayPage = (script: string, runs: number = 1): FakeNode => {
  const root = createNode();
  const button = createNode();
  button.id = 'gpay-button-online-api-id';
  root.appendChild(button);

  const fakeDocument = {
    head: null,
    documentElement: root,
    createElement: (): FakeNode => createNode(),
    getElementById: (id: string): FakeNode | null => findById(root, id),
    addEventListener: (): void => undefined,
  };

  for (let index = 0; index < runs; index += 1) {
    new Function('document', 'MutationObserver', script)(
      fakeDocument,
      undefined,
    );
  }

  return button;
};

const readFallbackTexts = (button: FakeNode): string[] => {
  const fallback = button.children.find(
    (child: FakeNode): boolean => child.id === 'heals-gpay-fallback',
  );

  return (fallback?.children ?? []).map(
    (child: FakeNode): string => child.textContent,
  );
};

describe('embeddedWebViewSafeAreaScript', () => {
  test('clears only the top safe-area inset that clips the embedded H5 title', () => {
    expect(embeddedWebViewSafeAreaScript).toContain('--k-safe-area-top:0px !important');
    expect(embeddedWebViewSafeAreaScript).not.toContain('--k-safe-area-bottom:0px');
  });

  test('keeps the original G Pay control clickable under the local fallback', () => {
    expect(embeddedWebViewSafeAreaScript).toContain('gpay-button-online-api-id');
    expect(embeddedWebViewSafeAreaScript).toContain('heals-gpay-fallback');
    expect(embeddedWebViewSafeAreaScript).toContain('pointer-events:none');
  });
});

describe('createEmbeddedWebViewSafeAreaScript', () => {
  test('draws the G Pay fallback with the supplied locale labels', () => {
    const button = runScriptOnGPayPage(
      createEmbeddedWebViewSafeAreaScript({
        prefix: '使用',
        suffix: 'Pay 付款',
      }),
    );

    expect(readFallbackTexts(button)).toEqual(['使用', '', 'Pay 付款']);
  });

  test('defaults to the English label instead of a hard-coded Chinese one', () => {
    const button = runScriptOnGPayPage(embeddedWebViewSafeAreaScript);

    expect(readFallbackTexts(button)).toEqual(['Buy with', '', 'Pay']);
  });

  test('installs the fallback only once when the script runs repeatedly', () => {
    const button = runScriptOnGPayPage(embeddedWebViewSafeAreaScript, 2);

    expect(
      button.children.filter(
        (child: FakeNode): boolean => child.id === 'heals-gpay-fallback',
      ),
    ).toHaveLength(1);
  });
});

