const ts = require('/Users/stark/Desktop/work/RN/heals-app-rn/node_modules/typescript');

const abs = (p) => path.join(root, p);
const cfgPath = `/tmp/heals-tsconfig-review-${path.basename(root)}.json`;
fs.writeFileSync(
  cfgPath,
  JSON.stringify({
    extends: path.join(root, 'tsconfig.json'),
    include: [
      path.join(root, 'src/**/*.ts'),
      path.join(root, 'src/**/*.tsx'),
      path.join(root, 'src/types/types.d.ts'),
      ...changedList.filter((f) => f.startsWith('__tests__/')).map(abs),
    ],
    compilerOptions: {module: 'esnext', noEmit: true},
  }),
);

const parsed = ts.getParsedCommandLineOfConfigFile(
  cfgPath,
  {},
  {...ts.sys, onUnRecoverableConfigFileDiagnostic: (d) => console.error(d.messageText)},
);
const host = {
  getScriptFileNames: () => parsed.fileNames,
  getScriptVersion: () => '1',
  getScriptSnapshot: (f) =>
    ts.sys.fileExists(f) ? ts.ScriptSnapshot.fromString(ts.sys.readFile(f)) : undefined,
  getCurrentDirectory: () => root,
  getCompilationSettings: () => parsed.options,
  getDefaultLibFileName: (o) => ts.getDefaultLibFilePath(o),
  fileExists: ts.sys.fileExists,
  readFile: ts.sys.readFile,
  readDirectory: ts.sys.readDirectory,
  directoryExists: ts.sys.directoryExists,
  getDirectories: ts.sys.getDirectories,
};
const ls = ts.createLanguageService(host, ts.createDocumentRegistry());
const rows = [];
const lineOf = (file, start) => {
  const sf = ls.getProgram().getSourceFile(file);
  return sf ? sf.getLineAndCharacterOfPosition(start).line + 1 : 0;
};
for (const rel of changedList) {
  if (!/\.(ts|tsx)$/.test(rel)) continue;
  const file = abs(rel);
  if (!fs.existsSync(file)) {
    rows.push({file: rel, kind: 'missing'});
    continue;
  }
  if (!ls.getProgram().getSourceFile(file)) {
    rows.push({file: rel, kind: 'not-in-program'});
    continue;
  }
  const kinds = {
    syntactic: ls.getSyntacticDiagnostics(file),
    semantic: ls.getSemanticDiagnostics(file),
    suggestion: ls.getSuggestionDiagnostics(file),
  };
  for (const [kind, diags] of Object.entries(kinds)) {
    for (const d of diags) {
      rows.push({
        file: rel,
        kind,
        code: d.code,
        line: lineOf(file, d.start || 0),
        message: ts.flattenDiagnosticMessageText(d.messageText, ' ').slice(0, 240),
      });
    }
  }
  rows.push({file: rel, kind: 'covered'});
}
fs.writeFileSync(outFile, JSON.stringify(rows, null, 1));
console.log('wrote', rows.length, 'rows to', outFile);

